starter_code:
create function prix_ttc(prix integer) returns integer
language sql immutable
as $$ select prix $$;

solution:
create function prix_ttc(prix integer) returns integer
language sql immutable
as $$ select round(prix * 1.18)::integer $$;

starter_code:
create function quantite_moyenne() returns numeric
language sql stable
as $$ select sum(quantite) / count(*) from commandes $$;

solution:
create function quantite_moyenne() returns numeric
language sql stable
as $$ select round(avg(quantite), 2) from commandes $$;

starter_code:
create function commandes_client(client uuid) returns table (produit text, quantite integer, statut text)
language sql stable
as $$ select p.nom, c.quantite, c.statut from commandes c join produits p on p.id = c.produit_id $$;
